 for(const side of [-1,1]){ellipsoid(side*(cat?.07:.09),-.07,cat?.17:.25,cat?.085:.11,cat?.07:.10,cat?.085:.18,cat?white:fur,head);ellipsoid(side*(cat?.10:.15),.025,cat?.16:.20,cat?.043:.047,cat?.038:.044,.025,white,head);ellipsoid(side*(cat?.10:.15),.025,cat?.183:.225,cat?.026:.025,cat?.03:.03,.01,new T.MeshStandardMaterial({color:cat?['#9cb36c','#9eae9d','#d2af5d'][variant%3]:'#65503b'}),head);ellipsoid(side*(cat?.10:.15),.025,cat?.193:.235,cat?.006:.013,.026,.006,dark,head);
 const ear=new T.Group();ear.position.set(side*(cat?.155:.20),cat?.17:.18,-.015);head.add(ear);if(cat){const e=new T.Mesh(new T.ConeGeometry(.105,.235,4),fur);e.rotation.y=Math.PI/4;ear.add(e);const inner=new T.Mesh(new T.ConeGeometry(.064,.16,4),pink);inner.position.set(0,.012,.035);inner.scale.z=.25;ear.add(inner);}else{ellipsoid(side*.025,-.08,-.035,.105,.25,.07,fur,ear);ear.rotation.z=side*.30;}
 if(cat)for(let k=0;k<3;k++){const pts=[new T.Vector3(side*.08,-.07+k*.018,.235),new T.Vector3(side*.31,-.08+(k-1)*.035,.25)],line=new T.Line(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color:'#b7b4a7'}));head.add(line);}
 for(const front of [false,true]){const pivot=new T.Group();pivot.position.set(side*(cat?.14:.22),cat?.51:.64,front?(cat?.29:.39):(cat?-.30:-.43));root.add(pivot);if(!front)ellipsoid(0,-.025,0,cat?.115:.16,.20,.18,fur,pivot);ellipsoid(0,cat?-.17:-.23,front?0:-.035,cat?.048:.07,cat?.21:.28,cat?.055:.08,fur,pivot);ellipsoid(0,cat?-.37:-.56,.05,cat?.072:.10,.055,cat?.11:.16,pattern===3||pattern===2?white:fur,pivot);legs.push(pivot);}}
 ellipsoid(0,-.055,cat?.245:.415,cat?.027:.06,cat?.022:.045,cat?.022:.035,cat?pink:dark,head);ellipsoid(0,-.12,cat?.21:.35,.045,.008,.018,dark,head);tail.position.set(0,cat?.67:.88,cat?-.45:-.57);root.add(tail);const curve=new T.CatmullRomCurve3([new T.Vector3(),new T.Vector3(0,cat?.2:.09,-.28),new T.Vector3(cat?.08:0,cat?.65:.38,cat?-.37:-.50)]);tail.add(new T.Mesh(new T.TubeGeometry(curve,14,cat?.035:.065,8,false),fur));
 // Raised markings hug the flanks instead of recolouring an entire animal.
 const mark=new T.MeshStandardMaterial({color:pattern===2?'#4e443a':pattern===3?'#e7e0cf':cat?'#66513f':'#6b5040',roughness:.98});for(const side of [-1,1])for(let i=0;i<(cat?7:4);i++){const z=-.32+i*(cat?.105:.19),stripe=ellipsoid(side*(cat?.202:.287),cat?.58:.75,z,cat?.013:.023,cat?.15:.20,cat?.022:.095,mark);stripe.rotation.x=(i%2?.25:-.2);if(pattern===2&&i%2)stripe.material=new T.MeshStandardMaterial({color:'#ad7548',roughness:.97});if(pattern===3)stripe.visible=i<2;}
 if(cat){for(let i=0;i<3;i++)ellipsoid((i-1)*.055,.105,.15,.012,.045,.025,dark,head);root.scale.setScalar(.9);}else{const collar=new T.Mesh(new T.TorusGeometry(.22,.025,8,24),new T.MeshStandardMaterial({color:['#8f4c37','#547a8d','#857047'][variant%3]}));collar.rotation.x=Math.PI/2;collar.position.set(0,.98,.44);root.add(collar);ellipsoid(0,.91,.64,.04,.055,.014,new T.MeshStandardMaterial({color:'#c4b475',metalness:.5,roughness:.4}));}
 batchRigidDetails(root); return {root,legs,tail,head,update(dt,a,moved){const walking=moved>0;for(let i=0;i<legs.length;i++)legs[i].rotation.x=walking?Math.sin(a.phase*(cat?9:8)+(i===0||i===3?0:Math.PI))*.43:a.mode==='rest'?.8:0;head.rotation.x=a.mode==='graze'?.55:a.mode==='look'?-.12:0;head.rotation.y=Math.sin(a.phase*.65)*.12;tail.rotation.z=Math.sin(a.phase*(cat?1.3:4))*(cat?.1:.32);root.position.y=.2+(a.mode==='rest'?-.15:Math.sin(a.phase*2)*.008);}};
